<?php
$allocated=0; $legacy=false;
foreach ($items as $item) { if ($item['excluido_em']!==null) { continue; } if ($item['total_centavos']===null) { $legacy=true; } else { $allocated+=(int)$item['total_centavos']; } }
$active=$record['excluido_em']===null;
$query=[];
if (isset($_GET['busca']) && is_string($_GET['busca'])) { $query['busca']=$_GET['busca']; }
if (($_GET['situacao'] ?? '')==='excluidos') { $query['situacao']='excluidos'; }
if (isset($_GET['pagina']) && filter_var($_GET['pagina'],FILTER_VALIDATE_INT)) { $query['pagina']=$_GET['pagina']; }
$back='contrato'.($query ? '?'.http_build_query($query) : '');
$formatDate=static function (?string $value,bool $dateOnly=false): string {
    if (!$value) { return 'Não registrado'; }
    try { return $dateOnly ? (new DateTimeImmutable($value))->format('d/m/Y') :
        (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(Config::string('APP_TIMEZONE','America/Cuiaba')))->format('d/m/Y H:i'); }
    catch (Exception) { return 'Data indisponível'; }
};
?>
<section class="relatorio modulo5-hero">
<p><a href="<?= e(url($back)) ?>">Voltar aos contratos</a> · <a href="<?= e(url('contrato/imprimir/'.$record['id'])) ?>" target="_blank" rel="noopener">Imprimir contrato</a></p>
<h2><?= e($record['titulo']) ?> <?= !$active ? '(excluído)' : '' ?></h2>
<p>Fornecedor: <?= e($record['fornecedor'] ?? 'Não informado') ?><?php if (!$active): ?> · Excluído em <?= e($formatDate($record['excluido_em'])) ?> por <?= e($record['excluido_por_nome'] ?? 'Usuário indisponível') ?><?php endif; ?></p>
<div class="modulo5-metrics"><div><strong><?= e(Contrato::money($record['valor_centavos']===null ? null : (int)$record['valor_centavos'])) ?></strong><span>Valor contratado</span></div><div><strong><?= $legacy ? 'Revisão pendente' : e(Contrato::money($allocated)) ?></strong><span>Distribuído em produtos</span></div><div><strong><?= $legacy || $record['valor_centavos']===null ? 'Revisão pendente' : e(Contrato::money((int)$record['valor_centavos']-$allocated)) ?></strong><span>Saldo contratual</span></div></div>
<?php if ($active): ?><p><a class="btn btn-outline-primary" href="<?= e(url('contrato/editar/'.$record['id'])) ?>">Editar dados gerais</a></p><?php endif; ?>
