<?php if ($isAdmin && $active && $record['valor_centavos']===null): ?><details><summary>Conciliar valor contratado legado</summary><p>Confira os documentos de origem. Os itens devem ser conciliados primeiro; a operação é auditada.</p><form method="post" action="<?= e(url('contrato/conciliar/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="produto" value=""><input type="hidden" name="revisao" value="<?= (int)$record['revisao'] ?>"><label>Valor confirmado R$ <input name="valor" inputmode="decimal" required></label><button class="btn btn-primary">Conciliar</button></form></details><?php endif; ?>
